"use client";

import { toast } from "sonner";
import { defineSchema, type InferType } from "@buildnbuzz/form-react";
import {
  Form,
  FormContent,
  FormFields,
  FormSubmit,
} from "@/registry/shadcn/form";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

// Pricing plan selection with card variant
const pricingSchema = defineSchema({
  fields: [
    {
      type: "radio",
      name: "plan",
      label: "Select your plan",
      required: true,
      options: [
        {
          value: "free",
          label: "Free",
          description: "For personal projects and experiments",
        },
        {
          value: "pro",
          label: "Pro",
          description: "For professional developers and small teams",
        },
        {
          value: "enterprise",
          label: "Enterprise",
          description: "For large organizations with custom needs",
        },
      ],
      ui: {
        variant: "card",
        card: { size: "md", bordered: true },
      },
    },
    {
      type: "radio",
      name: "billing",
      label: "Billing cycle",
      required: true,
      options: ["Monthly", "Yearly"],
      defaultValue: "Monthly",
      ui: { direction: "horizontal" },
    },
  ],
});

type PricingSchema = InferType<typeof pricingSchema.fields>;

export default function PricingFormCard() {
  const handleSubmit = async ({ value }: { value: unknown }) => {
    const data = value as PricingSchema;
    await new Promise((resolve) => setTimeout(resolve, 500));
    toast("Plan selected!", {
      description: (
        <pre className="mt-2 max-h-48 overflow-auto rounded-md bg-muted text-muted-foreground p-3 text-xs">
          <code>{JSON.stringify(data, null, 2)}</code>
        </pre>
      ),
    });
  };

  return (
    <Card className="w-full max-w-md">
      <CardHeader>
        <CardTitle>Choose a Plan</CardTitle>
        <CardDescription>
          Select the plan that best fits your needs.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Form schema={pricingSchema} onSubmit={handleSubmit}>
          <FormContent className="space-y-6">
            <FormFields />
            <FormSubmit className="w-full">Continue</FormSubmit>
          </FormContent>
        </Form>
      </CardContent>
    </Card>
  );
}
